-- Automatisch erzeugt von scripts/generate-seed.ts – nicht von Hand ändern.

on conflict (slug) do update set name_de = excluded.name_de, name_en = excluded.name_en, primary_muscle = excluded.primary_muscle,
  secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, is_bodyweight = excluded.is_bodyweight,
  ranking_type = excluded.ranking_type, standards = excluded.standards;

on conflict (id) do update set category = excluded.category, name_de = excluded.name_de, name_en = excluded.name_en,
  desc_de = excluded.desc_de, desc_en = excluded.desc_en, sort = excluded.sort;
